name = "SeasonZ";
tooltip = "SeasonZ";
overview = "Seasons follow the real date or their own adjustable clock, with a climate based on Kyiv. Weather, lighting, colours and trees change with the season. Winter brings snowfall and snow that builds up and melts on the ground, roofs and trees, with footprints and tyre tracks in it, and a winter haze while snow lies. Ponds and lakes freeze over and carry players once the ice is thick enough, and winter makes food scarce: crops stop growing in the cold and die in hard frost outdoors, greenhouses protect them down to -12 C.";
version = "0.5.3";
